                const token = await getAdminToken();
                const res = await sourceFetch(`/api/admin/communications/recordings?callSid=${encodeURIComponent(sid)}`, {
                    headers: { authorization: `Bearer ${token}` },
                });
                if (res.ok) {
                    const data = await res.json();
                    setCallRecordings((prev) => ({ ...prev, [sid]: data.recordings ?? [] }));
                }
            }
            finally {
                setLoadingRecordings((prev) => ({ ...prev, [sid]: false }));
            }
        }
        if (!callNotes[sid]) {
            loadNotes(sid);
        }
    }
    async function transcribeRecording(recordingSid: string) {
        setTranscribing((prev) => ({ ...prev, [recordingSid]: true }));
        try {
            const token = await getAdminToken();
            const res = await sourceFetch("/api/ctrlp/admin/communications/transcribe", {
                method: "POST",
                headers: { "content-type": "application/json", authorization: `Bearer ${token}` },
                body: JSON.stringify({ recordingSid }),
            });
            const data = await res.json().catch(() => ({}));
            if (res.ok) {
                setTranscripts((prev) => ({ ...prev, [recordingSid]: data.transcript }));
            }
            else {
                setTranscripts((prev) => ({ ...prev, [recordingSid]: data.error || "Transcription failed." }));
            }
        }
        finally {
            setTranscribing((prev) => ({ ...prev, [recordingSid]: false }));
        }
    }
    // Notes
    async function loadNotes(callSid: string) {
        try {
            const token = await getAdminToken();
            const res = await sourceFetch(`/api/admin/communications/calls/notes?callSid=${encodeURIComponent(callSid)}`, {
                headers: { authorization: `Bearer ${token}` },
            });
            if (res.ok) {
                const data = await res.json();
                setCallNotes((prev) => ({ ...prev, [callSid]: data.notes ?? [] }));
            }
        }
        catch { /* silent */ }
    }
    async function saveNote(callSid: string) {
        const note = (noteInput[callSid] || "").trim();
        if (!note)
            return;
        setSavingNote((prev) => ({ ...prev, [callSid]: true }));
        try {
            const token = await getAdminToken();
            await sourceFetch("/api/ctrlp/admin/communications/calls/notes", {
                method: "POST",
                headers: { "content-type": "application/json", authorization: `Bearer ${token}` },
                body: JSON.stringify({ callSid, note }),
            });
            setNoteInput((prev) => ({ ...prev, [callSid]: "" }));
            await loadNotes(callSid);
        }
        finally {
            setSavingNote((prev) => ({ ...prev, [callSid]: false }));
        }
    }
    async function deleteNote(callSid: string, noteId: string) {
        setDeletingNote((prev) => ({ ...prev, [noteId]: true }));
        try {
            const token = await getAdminToken();
            await sourceFetch(`/api/admin/communications/calls/notes?id=${encodeURIComponent(noteId)}`, {
                method: "DELETE",
                headers: { authorization: `Bearer ${token}` },
            });
            await loadNotes(callSid);
        }
        finally {
            setDeletingNote((prev) => ({ ...prev, [noteId]: false }));
        }
    }
    // Contacts
    async function loadContacts() {
        try {
            const token = await getAdminToken();
            const [usersRes, contactsRes] = await Promise.all([
                sourceFetch("/api/ctrlp/admin/users", { headers: { authorization: `Bearer ${token}` } }),
                sourceFetch("/api/ctrlp/admin/contact-submissions", { headers: { authorization: `Bearer ${token}` } }),
            ]);
            const rows: ContactRow[] = [];
            if (usersRes.ok) {
                const data = await usersRes.json();
                (data.users ?? []).forEach((u: {
                    id: string;
                    full_name?: string;
                    email?: string;
                    phone?: string;
                    company?: string;
                }) => {
                    rows.push({ id: u.id, name: u.full_name || u.email || "Unknown", email: u.email || null, phone: u.phone || null, company: u.company || null, source: "user" });
                });
            }
            if (contactsRes.ok) {
                const data = await contactsRes.json();
                (data.submissions ?? []).forEach((s: {
                    id: string;
                    first_name: string;
                    last_name?: string;
                    email: string;
                    phone?: string;
                    company?: string;
                }) => {
                    rows.push({
                        id: s.id,
                        name: [s.first_name, s.last_name].filter(Boolean).join(" "),
                        email: s.email,
                        phone: s.phone || null,
                        company: s.company || null,
                        source: "contact",
                    });
                });
            }
            setContacts(rows);
        }
        catch { /* silent */ }
    }
    // SMS send
    async function sendSms() {
        if (!smsTo.trim() || !smsBody.trim())
            return;
        setSmsSending(true);
        setSmsStatus("");
        try {
            const token = await getAdminToken();
            const res = await sourceFetch("/api/ctrlp/admin/messaging/send", {
                method: "POST",
                headers: { "content-type": "application/json", authorization: `Bearer ${token}` },
                body: JSON.stringify({ channel: "sms", mode: "single", recipient: smsTo.trim(), body: smsBody.trim() }),
            });
            const data = await res.json().catch(() => ({}));
            if (res.ok) {
                setSmsStatus(`Sent successfully.`);
                setSmsBody("");
            }
            else {
                setSmsStatus(data.error || "Send failed.");
            }
        }
        catch {
            setSmsStatus("Send failed.");
        }
        finally {
            setSmsSending(false);
        }
    }
    // Derived
    const filteredContacts = useMemo(() => {
        const needle = contactSearch.toLowerCase();
        if (!needle)
            return contacts;
        return contacts.filter((c) => [c.name, c.email, c.phone, c.company].some((v) => String(v || "").toLowerCase().includes(needle)));
    }, [contacts, contactSearch]);
    // Our own Twilio numbers, normalized — used to reliably tell which side of a
    // call is the customer, since Twilio's `direction` is unreliable for calls
    // placed from the browser.
    const ownNumbers = useMemo(() => {
        const set = new Set<string>();
        availableNumbers.forEach((n) => set.add(normalizeNumber(n)));
        if (phoneNumber)
            set.add(normalizeNumber(phoneNumber));
        return set;
    }, [availableNumbers, phoneNumber]);
    const callIsOutbound = useCallback((call: TwilioCall): boolean => {
        const fromOwn = ownNumbers.has(normalizeNumber(call.from));
        const toOwn = ownNumbers.has(normalizeNumber(call.to));
        if (fromOwn && !toOwn)
            return true;
        if (toOwn && !fromOwn)
            return false;
        return call.direction.startsWith("outbound");
    }, [ownNumbers]);
    // The other party (customer) number — the side that isn't one of our numbers.
    const callOtherParty = useCallback((call: TwilioCall): string => {
        return callIsOutbound(call) ? call.to : call.from;
    }, [callIsOutbound]);
    const visibleCalls = useMemo(() => {
        let list = calls;
        if (historyTab === "voicemail") {
            list = list.filter((c) => c.direction === "inbound" && ["no-answer", "completed"].includes(c.status));
        }
        else if (directionFilter !== "all") {
            list = list.filter((c) => (directionFilter === "outbound" ? callIsOutbound(c) : !callIsOutbound(c)));
        }
        if (numberFilter) {
            list = list.filter((c) => normalizeNumber(callOtherParty(c)) === numberFilter);
        }
        return list;
    }, [calls, historyTab, directionFilter, numberFilter, callIsOutbound, callOtherParty]);
    const isCallActive = callState !== "idle";
    // ─── Sidebar nav shared with other admin pages ──────────────────────────────
    const orders = [] as {
        id: string;
    }[];
    const payments = [] as {
        id: string;
    }[];
    const messages = [] as {
        id: string;
    }[];
    return (<div className="source-module">
      <div className="min-h-full bg-background text-foreground">
        {/* Sidebar */}
        <></>

        {/* Header */}
        <></>

        {/* Main */}
        <main className="px-4 py-5  ">
          {authState === "checking" && (<Card><CardContent className="p-5 text-sm text-muted-foreground">Checking admin access...</CardContent></Card>)}
          {authState === "denied" && (<Card className="border-red-500/30">
              <CardContent className="p-5">
                <div className="font-semibold text-red-600 dark:text-red-300">Admin access required</div>
                <Button className="mt-4" asChild><a href="/login?redirect=/admin/communications">Go to login</a></Button>
              </CardContent>
            </Card>)}

          {authState === "allowed" && (<>
              {/* Page heading */}
              <div className="mb-5">
                <div className="flex items-center gap-2.5 mb-1">
                  <div className="flex h-8 w-8 items-center justify-center rounded-full bg-primary/15 text-primary">
                    <PhoneCall className="h-4 w-4"/>
                  </div>
                  <h1 className="text-[25px] font-semibold tracking-tight">Communications</h1>
                  <DeviceStatusDot status={deviceStatus}/>
                </div>
                <p className="text-sm text-muted-foreground">Voice calls, SMS messaging, contacts, and AI voice — powered by Twilio.</p>
              </div>

              {/* Tab navigation */}
              <div className="mb-5 flex gap-1 overflow-x-auto border-b pb-0 scrollbar-none">
                {([
                ["calls", PhoneCall, "Calls"],
                ["sms", MessageSquare, "SMS"],
                ["contacts", Users, "Contacts"],
                ["ai-voice", Bot, "AI Voice"],
                ["email", Mail, "Email"],
            ] as const).map(([tab, Icon, label]) => (<button key={tab} onClick={() => setActiveTab(tab)} className={cn("flex shrink-0 items-center gap-2 border-b-2 px-4 py-2.5 text-sm font-medium -mb-px transition-colors", activeTab === tab
                    ? "border-primary text-foreground"
                    : "border-transparent text-muted-foreground hover:text-foreground")}>
                    <Icon className="h-4 w-4"/>{label}
                  </button>))}
              </div>

              {/* Device error banner */}
              {deviceError && (<div className="mb-4 flex items-center gap-2 rounded-lg border border-red-300 dark:border-red-800 bg-red-50 dark:bg-red-900/20 px-3 py-2 text-sm text-red-700 dark:text-red-400">
                  <span className="flex-1">{deviceError}</span>
                  <button onClick={initTwilioDevice} className="shrink-0 rounded-md border px-2 py-0.5 text-xs hover:bg-red-100 dark:hover:bg-red-900/40">Retry</button>
                  <button onClick={() => setDeviceError("")} className="shrink-0"><X className="h-3.5 w-3.5"/></button>
                </div>)}

              {/* ─── CALLS TAB ─── */}
              {activeTab === "calls" && (<div className="grid gap-5 lg:grid-cols-[380px_1fr]">
                  {/* Dialpad */}
                  <Card className="h-fit">
                    <CardHeader className="pb-3">
                      <div className="flex items-center gap-2">
                        <PhoneCall className="h-4 w-4 text-primary"/>
                        <CardTitle className="text-base">Dialpad</CardTitle>
                      </div>
                    </CardHeader>
                    <CardContent className="space-y-4">
                      {/* Phone number display */}
                      <div className="relative">
                        <input type="tel" value={dialInput} onChange={(e) => setDialInput(e.target.value)} placeholder="Enter phone number" className="h-11 w-full rounded-lg border bg-secondary/30 px-4 text-center text-base font-mono tracking-wider placeholder:text-muted-foreground focus:outline-none focus:ring-2 focus:ring-ring" disabled={isCallActive}/>
                        {dialInput && !isCallActive && (<button onClick={() => setDialInput("")} className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground">
                            <X className="h-4 w-4"/>
                          </button>)}
                      </div>

                      {/* Active call display */}
                      {isCallActive && (<div className="rounded-lg border bg-primary/5 border-primary/20 p-3 text-center">
                          <div className="text-xs text-muted-foreground mb-1">
                            {callState === "connecting" && "Connecting..."}
                            {callState === "ringing" && "Ringing..."}
                            {callState === "active" && formatDuration(callDuration)}
                            {callState === "disconnecting" && "Disconnecting..."}
                          </div>
                          <div className="text-sm font-semibold">{formatPhone(dialInput) || "Unknown"}</div>
                        </div>)}

                      {/* Key pad */}
                      {!isCallActive && (<div className="grid grid-cols-3 gap-2">
                          {[
                        ["1", ""], ["2", "ABC"], ["3", "DEF"],
                        ["4", "GHI"], ["5", "JKL"], ["6", "MNO"],
                        ["7", "PQRS"], ["8", "TUV"], ["9", "WXYZ"],
                        ["*", ""], ["0", ""], ["#", ""],
                    ].map(([digit, letters]) => (<button key={digit} onClick={() => pressKey(digit)} className="flex h-14 flex-col items-center justify-center rounded-xl border bg-secondary/30 font-semibold transition-colors hover:bg-accent active:scale-95">
                              <span className="text-xl leading-none">{digit}</span>
                              {letters && <span className="mt-0.5 text-[9px] font-medium tracking-widest text-muted-foreground">{letters}</span>}
                            </button>))}
                        </div>)}

                      {/* In-call actions */}
                      {isCallActive && (<div className="grid grid-cols-4 gap-2">
                          <button onClick={toggleMute} className={cn("flex h-14 flex-col items-center justify-center rounded-xl border gap-1 text-xs font-medium transition-colors", isMuted ? "bg-red-500/15 border-red-400 text-red-600" : "bg-secondary/30 hover:bg-accent")}>
                            {isMuted ? <MicOff className="h-4 w-4"/> : <Mic className="h-4 w-4"/>}
                            {isMuted ? "Unmute" : "Mute"}
                          </button>
                          <button onClick={() => setIsOnHold(!isOnHold)} className={cn("flex h-14 flex-col items-center justify-center rounded-xl border gap-1 text-xs font-medium transition-colors", isOnHold ? "bg-orange-500/15 border-orange-400 text-orange-600" : "bg-secondary/30 hover:bg-accent")}>
                            <Pause className="h-4 w-4"/>
                            {isOnHold ? "Resume" : "Hold"}
                          </button>
                          <button onClick={startRecording} disabled={isRecording || !activeCallSid} className={cn("flex h-14 flex-col items-center justify-center rounded-xl border gap-1 text-xs font-medium transition-colors", isRecording
                        ? "bg-red-500/15 border-red-400 text-red-600"
                        : "bg-secondary/30 hover:bg-accent disabled:opacity-40")}>
                            {isRecording
                        ? <Circle className="h-4 w-4 fill-red-500 text-red-500 animate-pulse"/>
                        : <Disc className="h-4 w-4"/>}
                            {isRecording ? "Recording" : "Record"}
                          </button>
                          <button className="flex h-14 flex-col items-center justify-center rounded-xl border bg-secondary/30 gap-1 text-xs font-medium hover:bg-accent">
                            <Phone className="h-4 w-4"/>
                            Keypad
                          </button>
                        </div>)}

                      {/* Call / Hang up button */}
                      {!isCallActive ? (<button onClick={makeCall} disabled={!dialInput.trim() || deviceStatus !== "registered"} className="flex h-12 w-full items-center justify-center gap-2 rounded-xl bg-emerald-500 font-semibold text-white transition-all hover:bg-emerald-600 disabled:opacity-50 disabled:cursor-not-allowed">
                          <Phone className="h-5 w-5"/>
                          Call
                        </button>) : (<button onClick={hangUp} className="flex h-12 w-full items-center justify-center gap-2 rounded-xl bg-red-500 font-semibold text-white transition-all hover:bg-red-600">
                          <PhoneOff className="h-5 w-5"/>
                          Hang up
                        </button>)}

                      {/* Device status */}
                      <div className="flex items-center justify-center gap-1.5 text-[11px] text-muted-foreground">
                        <span className={cn("h-1.5 w-1.5 rounded-full", deviceStatus === "registered" ? "bg-emerald-500" : deviceStatus === "registering" ? "bg-yellow-500 animate-pulse" : "bg-red-500")}/>
                        {deviceStatus === "registered" && "Ready to call"}
                        {deviceStatus === "registering" && "Connecting..."}
                        {deviceStatus === "unregistered" && "Not connected"}
                        {deviceStatus === "error" && "Connection error"}
                        {phoneNumber && <span className="ml-1 opacity-70">· {formatPhone(phoneNumber)}</span>}
                      </div>
                    </CardContent>
                  </Card>

                  {/* Call history */}
                  <div>
                    {/* Caller ID selector */}
                    {availableNumbers.length > 0 && (<div className="mb-3">
                        <div className="mb-1.5 text-[10px] font-semibold uppercase tracking-wider text-muted-foreground">Dial out from</div>
                        <div className="flex flex-wrap gap-2">
                          {availableNumbers.map((num) => {
                        const isSelected = num === selectedCallerId;
                        return (<button key={num} onClick={() => setSelectedCallerId(num)} disabled={isCallActive} className={cn("flex items-center gap-1.5 rounded-lg border px-3 py-1.5 text-xs font-medium transition-colors disabled:opacity-50", isSelected
                                ? "border-primary bg-primary/10 text-primary"
                                : "border-border bg-secondary/30 text-muted-foreground hover:bg-accent hover:text-foreground")}>
                                <Phone className={cn("h-3 w-3", isSelected && "text-primary")}/>
                                {formatPhone(num)}
                              </button>);
                    })}
                        </div>
                      </div>)}

                    <div className="mb-3 flex items-center justify-between">
                      {/* Sub-tabs: Call History / Voicemail */}
                      <div className="flex items-center gap-1 rounded-lg border bg-secondary/40 p-1">
                        <button onClick={() => { setHistoryTab("calls"); loadCalls(false); }} className={cn("flex items-center gap-1.5 rounded-md px-3 py-1.5 text-xs font-medium transition-colors", historyTab === "calls" ? "bg-background shadow-sm text-foreground" : "text-muted-foreground hover:text-foreground")}>
                          <Clock className="h-3.5 w-3.5"/>Call History
                        </button>
                        <button onClick={() => { setHistoryTab("voicemail"); }} className={cn("flex items-center gap-1.5 rounded-md px-3 py-1.5 text-xs font-medium transition-colors", historyTab === "voicemail" ? "bg-background shadow-sm text-foreground" : "text-muted-foreground hover:text-foreground")}>
                          <Voicemail className="h-3.5 w-3.5"/>Voicemail
                        </button>
                      </div>
                      <div className="flex items-center gap-2">
                        <span className="text-sm text-muted-foreground">{visibleCalls.length} {historyTab === "voicemail" ? "messages" : "calls"}</span>
                        <Button variant="outline" size="sm" onClick={() => loadCalls(historyTab === "voicemail")} disabled={callsLoading} className="h-7 gap-1.5 text-xs">
                          <RefreshCw className={cn("h-3 w-3", callsLoading && "animate-spin")}/>Refresh
                        </Button>
                      </div>
                    </div>

                    {/* Direction filter: All / Inbound / Outbound */}
                    {historyTab === "calls" && (<div className="mb-3 flex items-center gap-1.5">
                        {([
                        ["all", "All", null],
                        ["inbound", "Inbound", PhoneIncoming],
                        ["outbound", "Outbound", PhoneOutgoing],
                    ] as const).map(([key, label, Icon]) => {
                        const isActive = directionFilter === key;
                        return (<button key={key} onClick={() => setDirectionFilter(key)} className={cn("flex items-center gap-1.5 rounded-lg border px-3 py-1.5 text-xs font-medium transition-colors", isActive
                                ? "border-primary bg-primary/10 text-primary"
                                : "border-border bg-secondary/30 text-muted-foreground hover:bg-accent hover:text-foreground")}>
                              {Icon && <Icon className="h-3.5 w-3.5"/>}
                              {label}
                            </button>);
                    })}
                      </div>)}

                    {/* Active number filter */}
                    {numberFilter && (<div className="mb-3 flex items-center gap-2 rounded-lg border border-primary/30 bg-primary/5 px-3 py-2 text-sm">
                        <Phone className="h-3.5 w-3.5 shrink-0 text-primary"/>
                        <span className="text-muted-foreground">Showing calls with</span>
                        <span className="font-semibold">{formatPhone(numberFilter)}</span>
                        <button onClick={() => setNumberFilter(null)} className="ml-auto flex shrink-0 items-center gap-1 rounded-md border px-2 py-0.5 text-xs text-muted-foreground hover:text-foreground">
                          <X className="h-3 w-3"/>Clear filter
                        </button>
                      </div>)}

                    {/* Call list */}
                    <div className="space-y-2">
                      {callsLoading && !calls.length && (Array.from({ length: 4 }).map((_, i) => (<div key={i} className="h-16 animate-pulse rounded-xl bg-secondary"/>)))}
                      {!callsLoading && !visibleCalls.length && (<Card>
                          <CardContent className="p-8 text-center text-muted-foreground">
                            {numberFilter
                        ? `No ${historyTab === "voicemail" ? "voicemail" : "calls"} with ${formatPhone(numberFilter)}.`
                        : historyTab === "voicemail" ? "No voicemail messages." : "No call history yet."}
                          </CardContent>
                        </Card>)}
                      {visibleCalls.map((call) => {
                    const isExpanded = expandedCallSid === call.sid;
                    const recordings = callRecordings[call.sid] ?? [];
                    const loadingRec = loadingRecordings[call.sid];
                    const isOutbound = callIsOutbound(call);
                    const displayNumber = callOtherParty(call);
                    const hasRecording = isExpanded && recordings.length > 0;
                    return (<Card key={call.sid} className={cn("overflow-hidden transition-shadow", isExpanded && "ring-1 ring-primary/20")}>
                            {/* Call row header */}
                            <button onClick={() => toggleCallExpand(call.sid)} className="flex w-full items-center gap-3 p-3 hover:bg-accent/40 transition-colors text-left">
                              <div className="grid h-9 w-9 shrink-0 place-items-center rounded-full border bg-secondary/50">
                                <CallDirectionIcon direction={isOutbound ? "outbound" : "inbound"} status={call.status}/>
                              </div>
                              <div className="flex-1 min-w-0">
                                <div className="flex items-center gap-2 flex-wrap">
                                  <span role="button" tabIndex={0} onClick={(e) => {
                            e.stopPropagation();
                            const digits = normalizeNumber(displayNumber);
                            setNumberFilter((prev) => (prev === digits ? null : digits));
                        }} onKeyDown={(e) => {
                            if (e.key === "Enter" || e.key === " ") {
                                e.preventDefault();
                                e.stopPropagation();
                                const digits = normalizeNumber(displayNumber);
                                setNumberFilter((prev) => (prev === digits ? null : digits));
                            }
                        }} className="font-semibold text-sm cursor-pointer rounded hover:text-primary hover:underline underline-offset-2" title="Show only calls with this number">
                                    {formatPhone(displayNumber)}
                                  </span>
                                  <CallStatusBadge status={call.status}/>
                                  {recordings.length > 0 && (<Badge className="bg-purple-500/15 text-purple-700 dark:text-purple-300 text-[10px] px-1.5 py-0">
                                      <Play className="mr-0.5 h-2.5 w-2.5 inline"/>Recorded
                                    </Badge>)}
                                </div>
                                <div className="mt-0.5 flex items-center gap-2 text-[11px] text-muted-foreground">
                                  <Clock className="h-3 w-3"/>
                                  <span>{formatDuration(call.duration)}</span>
                                </div>
                              </div>
                              <div className="shrink-0 flex items-center gap-2">
                                <span className="text-xs text-muted-foreground">{formatDateShort(call.dateCreated)}</span>
                                <ChevronDown className={cn("h-4 w-4 text-muted-foreground transition-transform", isExpanded && "rotate-180")}/>
                              </div>
                            </button>

                            {/* Expanded details */}
                            {isExpanded && (<div className="border-t bg-secondary/10">
                                <div className="grid grid-cols-4 gap-4 px-4 py-3">
                                  <div>
                                    <div className="text-[10px] text-muted-foreground uppercase tracking-wide">Direction</div>
                                    <div className="text-sm font-medium mt-0.5">
                                      {isOutbound ? "Outbound" : "Inbound"}
                                    </div>
                                  </div>
                                  <div>
                                    <div className="text-[10px] text-muted-foreground uppercase tracking-wide">Duration</div>
                                    <div className="text-sm font-medium mt-0.5">{formatDuration(call.duration)}</div>
                                  </div>
                                  <div>
                                    <div className="text-[10px] text-muted-foreground uppercase tracking-wide">Date &amp; Time</div>
                                    <div className="text-sm font-medium mt-0.5">{formatDateTime(call.dateCreated)}</div>
                                  </div>
                                  <div>
                                    <div className="text-[10px] text-muted-foreground uppercase tracking-wide">Est. Cost</div>
                                    <div className="text-sm font-medium mt-0.5 text-emerald-600 dark:text-emerald-400">
                                      {formatEstCost(call.price)}
                                    </div>
                                  </div>
                                </div>

                                {/* Dial back quick action */}
                                <div className="flex items-center gap-2 px-4 pb-3">
                                  <Button size="sm" variant="outline" className="h-7 gap-1.5 text-xs" onClick={() => {
                                setActiveTab("calls");
                                setDialInput(displayNumber);
                            }}>
                                    <Phone className="h-3 w-3"/>Call back
                                  </Button>
                                  <Button size="sm" variant="outline" className="h-7 gap-1.5 text-xs" onClick={() => {
