// ─── Block Editor ──────────────────────────────────────────────────────────────
function BlockEditor({ blocks, onChange }: {
    blocks: ContentBlock[];
    onChange: (b: ContentBlock[]) => void;
}) {
    const [dragIdx, setDragIdx] = useState<number | null>(null);
    const [dropIdx, setDropIdx] = useState<number | null>(null);
    const [addOpen, setAddOpen] = useState(false);
    function update(id: string, patch: Partial<ContentBlock>) {
        onChange(blocks.map((b) => b.id === id ? { ...b, ...patch } : b));
    }
    function remove(id: string) { onChange(blocks.filter((b) => b.id !== id)); }
    function addBlock(type: BlockType) {
        onChange([...blocks, { id: uid(), type, content: "" }]);
        setAddOpen(false);
    }
    function drop(toIdx: number) {
        if (dragIdx === null || dragIdx === toIdx)
            return;
        const next = [...blocks];
        const [moved] = next.splice(dragIdx, 1);
        next.splice(toIdx, 0, moved);
        onChange(next);
        setDragIdx(null);
        setDropIdx(null);
    }
    return (<div className="space-y-2">
      {blocks.map((block, i) => (<div key={block.id} draggable onDragStart={() => setDragIdx(i)} onDragOver={(e) => { e.preventDefault(); setDropIdx(i); }} onDragEnd={() => { setDragIdx(null); setDropIdx(null); }} onDrop={() => drop(i)} className={cn("group flex gap-2 rounded-lg border bg-card/50 p-2 transition-all", dropIdx === i && dragIdx !== i && "border-primary/60 bg-primary/5")}>
          <div className="flex flex-col gap-1 pt-1">
            <button type="button" className="cursor-grab text-muted-foreground opacity-0 group-hover:opacity-100 active:cursor-grabbing">
              <GripVertical className="h-4 w-4"/>
            </button>
          </div>
          <div className="flex-1 space-y-1.5">
            {block.type === "hr" ? (<div className="my-2 border-t border-border"/>) : block.type === "img" ? (<div className="space-y-1.5">
                <Input placeholder="Image URL" value={block.content} onChange={(e) => update(block.id, { content: e.target.value })} className="text-sm"/>
                <div className="flex gap-2">
                  <Input placeholder="Alt text" value={block.alt || ""} onChange={(e) => update(block.id, { alt: e.target.value })} className="text-xs"/>
                  <Input placeholder="Caption (optional)" value={block.caption || ""} onChange={(e) => update(block.id, { caption: e.target.value })} className="text-xs"/>
                </div>
                {block.content && <img src={block.content} alt={block.alt} className="mt-1 max-h-[120px] rounded object-cover"/>}
              </div>) : block.type === "video" ? (<div className="space-y-1.5">
                <Input placeholder="Video embed URL (YouTube, Vimeo, etc.)" value={block.content} onChange={(e) => update(block.id, { content: e.target.value })} className="text-sm"/>
                <Input placeholder="Caption (optional)" value={block.caption || ""} onChange={(e) => update(block.id, { caption: e.target.value })} className="text-xs"/>
              </div>) : block.type === "list" ? (<Textarea placeholder="One item per line" value={block.content} onChange={(e) => update(block.id, { content: e.target.value })} className={cn("min-h-[80px] resize-none text-sm")}/>) : (<Textarea placeholder={block.type === "quote" ? "Quote text…" : block.type === "h1" ? "Heading 1…" : block.type === "h2" ? "Heading 2…" : block.type === "h3" ? "Heading 3…" : "Paragraph text…"} value={block.content} onChange={(e) => update(block.id, { content: e.target.value })} className={cn("min-h-[52px] resize-none border-0 bg-transparent p-0 shadow-none focus-visible:ring-0", block.type === "h1" && "text-2xl font-bold", block.type === "h2" && "text-xl font-semibold", block.type === "h3" && "text-lg font-medium", block.type === "quote" && "border-l-2 border-primary/40 pl-3 italic")}/>)}
          </div>
          <div className="flex flex-col gap-1 pt-1">
            <span className="text-[10px] text-muted-foreground opacity-0 group-hover:opacity-100">{block.type}</span>
            <button type="button" onClick={() => remove(block.id)} className="rounded p-0.5 text-muted-foreground opacity-0 hover:text-red-500 group-hover:opacity-100">
              <X className="h-3.5 w-3.5"/>
            </button>
          </div>
        </div>))}

      {/* Add block */}
      <div className="relative">
        <Button type="button" variant="outline" size="sm" className="h-7 gap-1.5 text-xs" onClick={() => setAddOpen(!addOpen)}>
          <Plus className="h-3.5 w-3.5"/> Add block
        </Button>
        {addOpen && (<div className="absolute left-0 top-8 z-10 w-52 rounded-lg border bg-card shadow-lg">
            {BLOCK_TYPES.map(({ type, label, icon: Icon }) => (<button key={type} type="button" onClick={() => addBlock(type)} className="flex w-full items-center gap-2.5 px-3 py-2 text-left text-[13px] hover:bg-accent">
                <Icon className="h-3.5 w-3.5 text-muted-foreground"/> {label}
              </button>))}
          </div>)}
      </div>
    </div>);
}
// ─── Calendar View ─────────────────────────────────────────────────────────────
function CalendarView({ items, month, onMonth }: {
    items: ContentItem[];
    month: Date;
    onMonth: (d: Date) => void;
}) {
    const year = month.getFullYear();
    const mon = month.getMonth();
    const firstDay = new Date(year, mon, 1).getDay();
    const daysInMonth = new Date(year, mon + 1, 0).getDate();
    const cells = Array.from({ length: firstDay + daysInMonth }, (_, i) => i < firstDay ? null : i - firstDay + 1);
    const byDay: Record<number, ContentItem[]> = {};
    items.forEach((item) => {
        const d = item.published_at ? new Date(item.published_at) : null;
        if (d && d.getFullYear() === year && d.getMonth() === mon) {
            const day = d.getDate();
            (byDay[day] ??= []).push(item);
        }
    });
    const today = new Date();
    return (<div>
      <div className="mb-4 flex items-center gap-3">
        <Button variant="outline" size="icon" className="h-7 w-7" onClick={() => onMonth(new Date(year, mon - 1, 1))}>
          <ChevronLeft className="h-4 w-4"/>
        </Button>
        <span className="text-sm font-medium">{month.toLocaleDateString("en-US", { month: "long", year: "numeric" })}</span>
        <Button variant="outline" size="icon" className="h-7 w-7" onClick={() => onMonth(new Date(year, mon + 1, 1))}>
          <ChevronRight className="h-4 w-4"/>
        </Button>
      </div>
      <div className="grid grid-cols-7 gap-px overflow-hidden rounded-lg border bg-border">
        {["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"].map((d) => (<div key={d} className="bg-card px-2 py-1.5 text-center text-[11px] font-semibold text-muted-foreground">{d}</div>))}
        {cells.map((day, ci) => {
            const isToday = day !== null && today.getDate() === day && today.getMonth() === mon && today.getFullYear() === year;
            const dayItems = day ? (byDay[day] ?? []) : [];
            return (<div key={ci} className={cn("min-h-[80px] bg-card p-1.5", !day && "bg-muted/30")}>
              {day && (<>
                  <span className={cn("flex h-5 w-5 items-center justify-center rounded-full text-[12px]", isToday && "bg-primary text-primary-foreground font-semibold")}>{day}</span>
                  <div className="mt-1 space-y-0.5">
                    {dayItems.slice(0, 3).map((item) => {
                        const meta = TYPE_META[item.content_type];
                        return (<div key={item.id} className={cn("truncate rounded px-1 py-0.5 text-[10px] font-medium", meta.color)}>{item.title}</div>);
                    })}
                    {dayItems.length > 3 && <div className="text-[10px] text-muted-foreground">+{dayItems.length - 3} more</div>}
                  </div>
                </>)}
            </div>);
        })}
      </div>
    </div>);
}
