    if (["unpaid", "needs_changes", "file_review", "on_hold"].includes(status)) {
        return "border-red-500/20 bg-red-500/10 text-red-700 dark:text-red-300";
    }
    return "border-border bg-secondary text-secondary-foreground";
}
