function uid() { return Math.random().toString(36).slice(2); }
async function apiCall(method: string, body: Record<string, unknown>) {
    const db = getSupabaseBrowserClient();
    const token = (await db?.auth.getSession())?.data.session?.access_token;
    const res = await sourceFetch("/api/ctrlp/admin/content", {
        method,
        headers: { "content-type": "application/json", ...(token ? { authorization: `Bearer ${token}` } : {}) },
        body: JSON.stringify(body),
    });
    const json = await res.json().catch(() => ({})) as Record<string, unknown>;
    if (!res.ok)
        throw new Error(String(json.error || "Request failed"));
    return json;
}
async function getToken() {
    const db = getSupabaseBrowserClient();
    return (await db?.auth.getSession())?.data.session?.access_token ?? "";
}
async function adminGet<T>(path: string): Promise<T> {
    const token = await getToken();
    const res = await sourceFetch(path, { headers: { authorization: `Bearer ${token}` } });
    return res.json() as Promise<T>;
}
async function adminPost(path: string, body: Record<string, unknown>, method = "POST") {
    const token = await getToken();
    const res = await sourceFetch(path, {
        method, headers: { "content-type": "application/json", authorization: `Bearer ${token}` },
        body: JSON.stringify(body),
    });
    return res.json();
}
