    const [sendTo, setSendTo] = useState("");
    const [sendFrom, setSendFrom] = useState("Ctrl+P <noreply@ctrlp.io>");
    const [sendSubject, setSendSubject] = useState("");
    const [sendBody, setSendBody] = useState("");
    const [sendTemplateId, setSendTemplateId] = useState("__none__");
    const [sending, setSending] = useState(false);
    useEffect(() => {
        if (tab === "templates" || tab === "send") {
            setLoadingTemplates(true);
            fetchTemplates().then((t) => { setTemplates(t); setLoadingTemplates(false); });
        }
        if (tab === "submissions") {
            setSubLoading(true);
            adminGet<{
                submissions: Submission[];
            }>("/api/ctrlp/admin/communications/submissions")
                .then((r) => { setSubmissions(r.submissions ?? []); setSubLoading(false); });
        }
        if (tab === "inbox") {
            setInboxLoading(true);
            adminGet<{
                messages: InboxMessage[];
            }>("/api/ctrlp/admin/communications/inbox")
                .then((r) => { setInboxMessages(r.messages ?? []); setInboxLoading(false); });
        }
        if (tab === "automations") {
            setAutoLoading(true);
            adminGet<{
                automations: Automation[];
            }>("/api/ctrlp/admin/communications/automations")
                .then((r) => { setAutomations(r.automations ?? []); setAutoLoading(false); });
        }
        if (tab === "history") {
            setHistoryLoading(true);
            adminGet<{
