    const [installers, setInstallers] = useState<Installer[]>([]);
    const [bookings, setBookings] = useState<(InstallerBooking & {
        installer_profiles?: {
            name: string;
        };
    })[]>([]);
    const [loading, setLoading] = useState(false);
    const [search, setSearch] = useState("");
    const [sheetOpen, setSheetOpen] = useState(false);
    const [editing, setEditing] = useState<Installer | null>(null);
    const [saving, setSaving] = useState(false);
    const [message, setMessage] = useState("");
    const [view, setView] = useState<"roster" | "bookings">("roster");
    const orders = dashboardData?.orders ?? [];
    const payments = dashboardData?.payments ?? [];
    const messages = dashboardData?.messages ?? [];
    const users = dashboardData?.users ?? [];
    async function load() {
        const profile = await getCurrentAdminProfile();
        if (!profile && process.env.NEXT_PUBLIC_SUPABASE_URL) {
            setAuthState("denied");
            return;
        }
        setAuthState("allowed");
        setDashboardData(await loadAdminDashboardData());
        setLoading(true);
        try {
            const [dRes, bRes] = await Promise.all([
                adminFetch("/api/ctrlp/admin/installers?all=true"),
                sourceFetch("/api/ctrlp/installer-bookings?limit=100").then((r) => r.json()),
            ]);
            setInstallers(dRes.installers ?? []);
            setBookings(bRes.bookings ?? []);
        }
        catch (e) {
            setMessage(e instanceof Error ? e.message : "Failed to load.");
        }
        finally {
            setLoading(false);
        }
    }
    useEffect(() => { load(); }, []);
    async function handleSave(data: Partial<Installer>) {
        setSaving(true);
        setMessage("");
        try {
            if (editing) {
                await adminFetch("/api/ctrlp/admin/installers", {
                    method: "PATCH",
                    body: JSON.stringify({ id: editing.id, ...data }),
                });
                setMessage("Installer updated.");
            }
            else {
                await adminFetch("/api/ctrlp/admin/installers", {
                    method: "POST",
                    body: JSON.stringify(data),
                });
                setMessage("Installer created.");
            }
            setSheetOpen(false);
            setEditing(null);
            await load();
        }
        catch (e) {
            setMessage(e instanceof Error ? e.message : "Save failed.");
        }
        finally {
            setSaving(false);
        }
    }
    async function handleDelete(installer: Installer) {
        if (!window.confirm(`Deactivate "${installer.name}"? They won't appear to new customers.`))
            return;
        try {
            await adminFetch(`/api/admin/installers?id=${encodeURIComponent(installer.id)}`, { method: "DELETE" });
            setMessage("Installer deactivated.");
            await load();
        }
        catch (e) {
            setMessage(e instanceof Error ? e.message : "Delete failed.");
        }
    }
    function openCreate() {
        setEditing(null);
        setSheetOpen(true);
    }
    function openEdit(d: Installer) {
        setEditing(d);
        setSheetOpen(true);
    }
    const filteredInstallers = useMemo(() => {
        if (!search)
            return installers;
        const q = search.toLowerCase();
        return installers.filter((d) => d.name.toLowerCase().includes(q) ||
