                  {/* Stats */}
                  <section className="mb-5 grid gap-3 md:grid-cols-2 xl:grid-cols-4">
                    <MessageStat label="Total" value={String(contactSubmissions.length)} hint="All contact submissions"/>
                    <MessageStat label="New" value={String(contactNew)} hint="Awaiting response"/>
                    <MessageStat label="Replied" value={String(contactReplied)} hint="Marked as replied"/>
                    <MessageStat label="This Week" value={String(contactThisWeek)} hint="Last 7 days"/>
                  </section>

                  {/* Search + view toggle */}
                  <div className="mb-4 flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
                    <div className="relative sm:w-72">
                      <Search className="absolute left-3 top-2 h-4 w-4 text-muted-foreground"/>
                      <Input className="h-8 pl-9 text-xs" placeholder="Search name, email, subject..." value={contactQuery} onChange={(e) => setContactQuery(e.target.value)}/>
                    </div>
                    <div className="flex items-center gap-0.5 rounded-lg border bg-secondary/40 p-1 w-fit">
                      {(["table", "list", "calendar"] as const).map((v) => (<button key={v} onClick={() => setContactView(v)} className={cn("flex items-center gap-1.5 rounded-md px-3 py-1.5 text-xs font-medium capitalize transition-colors", contactView === v
                        ? "bg-background shadow-sm text-foreground"
                        : "text-muted-foreground hover:text-foreground")}>
                          {v === "table" && <Table2 className="h-3.5 w-3.5"/>}
                          {v === "list" && <List className="h-3.5 w-3.5"/>}
                          {v === "calendar" && <Calendar className="h-3.5 w-3.5"/>}
                          {v.charAt(0).toUpperCase() + v.slice(1)}
                        </button>))}
                    </div>
                  </div>

                  {contactView === "table" && (<ContactTableView submissions={visibleContacts} onSelect={openContact}/>)}
                  {contactView === "list" && (<ContactListView submissions={visibleContacts} onSelect={openContact}/>)}
                  {contactView === "calendar" && (<ContactCalendarView submissions={visibleContacts} month={contactCalendarMonth} onMonthChange={setContactCalendarMonth} selectedDay={selectedCalendarDay} onDaySelect={setSelectedCalendarDay} onSelect={openContact}/>)}
                </>)}

              {/* ── Booking Templates section ── */}
              {activeSection === "templates" && (<>
                  <div className="mb-4 grid gap-3 md:grid-cols-3">
                    <MessageStat label="Total" value={String(templates.length)} hint="All booking templates"/>
                    <MessageStat label="Email" value={String(templates.filter((t) => t.channel === "email").length)} hint="Email templates"/>
                    <MessageStat label="SMS" value={String(templates.filter((t) => t.channel === "sms").length)} hint="SMS templates"/>
                  </div>

                  <Card>
                    <CardHeader className="pb-3">
                      <CardTitle className="text-base">Booking &amp; Appointment Templates</CardTitle>
                      <CardDescription>Manage automated email and SMS message templates for booking confirmations, reminders, and updates.</CardDescription>
                    </CardHeader>
                    <CardContent className="p-0">
                      <Table>
                        <TableHeader>
                          <TableRow>
                            <TableHead className="pl-4">Template name</TableHead>
                            <TableHead>Channel</TableHead>
                            <TableHead>Type</TableHead>
                            <TableHead>Status</TableHead>
                            <TableHead className="w-[140px] min-w-[140px]">Updated</TableHead>
                            <TableHead className="w-[90px]"/>
                          </TableRow>
                        </TableHeader>
                        <TableBody>
                          {templates.map((template) => (<TableRow key={template.id}>
                              <TableCell className="pl-4">
                                <div className="font-medium">{template.name}</div>
                                <div className="line-clamp-1 text-xs text-muted-foreground">
                                  {template.channel === "email" && template.subject ? template.subject : template.body}
                                </div>
                              </TableCell>
                              <TableCell><ChannelBadge channel={template.channel}/></TableCell>
                              <TableCell className="text-sm">{human(template.notification_type)}</TableCell>
                              <TableCell>
                                <Badge className={template.is_active ? "bg-emerald-500/10 text-emerald-700 dark:text-emerald-300" : "bg-secondary text-secondary-foreground"}>
                                  {template.is_active ? "Active" : "Inactive"}
                                </Badge>
                              </TableCell>
                              <TableCell className="text-sm">{formatDate(template.updated_at)}</TableCell>
                              <TableCell>
                                <div className="flex items-center gap-1">
                                  <Button variant="ghost" size="icon" className="h-7 w-7" aria-label="Edit template" onClick={() => { setEditingTemplate(template); setTemplateFormOpen(true); }}>
                                    <Pencil className="h-3.5 w-3.5"/>
                                  </Button>
                                  {deletingTemplateId === template.id ? (<div className="flex items-center gap-1">
                                      <Button variant="destructive" size="sm" className="h-7 px-2 text-xs" onClick={() => deleteTemplate(template.id)}>Confirm</Button>
                                      <Button variant="ghost" size="sm" className="h-7 px-2 text-xs" onClick={() => setDeletingTemplateId(null)}>Cancel</Button>
                                    </div>) : (<Button variant="ghost" size="icon" className="h-7 w-7 text-destructive hover:text-destructive" aria-label="Delete template" onClick={() => setDeletingTemplateId(template.id)}>
                                      <Trash2 className="h-3.5 w-3.5"/>
                                    </Button>)}
                                </div>
                              </TableCell>
                            </TableRow>))}
                          {!templates.length && (<TableRow>
                              <TableCell className="p-8 text-center text-muted-foreground" colSpan={6}>
                                No templates yet. Click <strong>New template</strong> to create your first.
                              </TableCell>
                            </TableRow>)}
                        </TableBody>
                      </Table>
                    </CardContent>
                  </Card>
                </>)}
            </>)}
        </main>

        {/* Sheets */}
        <BookingTemplateSheet open={templateFormOpen} onOpenChange={setTemplateFormOpen} template={editingTemplate} onSaved={(saved) => {
            setTemplates((current) => {
                const idx = current.findIndex((t) => t.id === saved.id);
                return idx >= 0 ? current.map((t) => t.id === saved.id ? saved : t) : [saved, ...current];
            });
            setTemplateFormOpen(false);
            setEditingTemplate(null);
        }}/>
        <ComposeMessageSheet open={composeOpen} onOpenChange={(open) => { setComposeOpen(open); if (!open)
        setComposePrefill(null); }} orders={orders} users={users} config={config} prefill={composePrefill} onMessageSent={refreshData}/>
        <MessageDetailSheet message={selectedMessage} open={Boolean(selectedMessage)} onOpenChange={(open) => { if (!open)
        setSelectedMessageId(null); }} order={orders.find((o) => o.id === selectedMessage?.order_id) ?? null} user={users.find((u) => u.id === selectedMessage?.user_id) ?? null} onCompose={() => { setSelectedMessageId(null); setComposeOpen(true); }}/>
        <ContactSubmissionSheet submission={selectedContact} open={Boolean(selectedContact)} onOpenChange={(open) => { if (!open)
        setSelectedContactId(null); }} onStatusChange={handleContactStatusChange} onCompose={(prefill) => {
            setSelectedContactId(null);
            setComposePrefill(prefill);
            setComposeOpen(true);
        }}/>
      </div>
    </div>);
}
// ─── Auth helpers ─────────────────────────────────────────────────────────────
async function getAdminToken() {
    const db = getSupabaseBrowserClient();
    const session = db ? (await db.auth.getSession()).data.session : null;
    const token = session?.access_token;
    if (!token)
        throw new Error("Sign in again before using messaging.");
    return token;
}
async function loadMessagingConfig(): Promise<MessagingConfig | null> {
    const db = getSupabaseBrowserClient();
    const session = db ? (await db.auth.getSession()).data.session : null;
    if (!session)
        return null;
    const response = await sourceFetch("/api/ctrlp/admin/messaging/config", {
        headers: { authorization: `Bearer ${session.access_token}` },
    });
    if (!response.ok)
        return null;
    return response.json();
}
async function loadBookingTemplates(): Promise<BookingTemplate[]> {
    try {
        const token = await getAdminToken();
        const response = await sourceFetch("/api/ctrlp/admin/booking-templates", {
            headers: { authorization: `Bearer ${token}` },
        });
        if (!response.ok)
            return [];
        const payload = await response.json();
        return payload.templates ?? [];
    }
    catch {
        return [];
    }
}
async function loadContactSubmissions(): Promise<ContactSubmission[]> {
    try {
        const token = await getAdminToken();
        const response = await sourceFetch("/api/ctrlp/admin/contact-submissions", {
            headers: { authorization: `Bearer ${token}` },
        });
        if (!response.ok)
            return [];
        const payload = await response.json();
        return payload.submissions ?? [];
    }
    catch {
        return [];
    }
}
async function updateContactStatus(id: string, status: string) {
    const token = await getAdminToken();
    await sourceFetch("/api/ctrlp/admin/contact-submissions", {
        method: "PATCH",
        headers: { "content-type": "application/json", authorization: `Bearer ${token}` },
        body: JSON.stringify({ id, status }),
    });
}
// ─── Shared UI atoms ──────────────────────────────────────────────────────────
function MessageStat({ label, value, hint }: {
    label: string;
    value: string;
    hint: string;
}) {
    return (<Card>
      <CardContent className="p-4">
        <div className="text-[10px] font-semibold uppercase tracking-wide text-muted-foreground">{label}</div>
        <div className="mt-2 text-[22px] font-semibold leading-none">{value}</div>
        <div className="mt-2 text-[11px] text-muted-foreground">{hint}</div>
      </CardContent>
    </Card>);
}
function ChannelBadge({ channel }: {
    channel: string;
}) {
    const tone = channel === "sms"
        ? "bg-primary/15 text-foreground"
        : channel === "email"
            ? "bg-emerald-500/10 text-emerald-700 dark:text-emerald-300"
            : channel === "contact_form"
                ? "bg-blue-500/10 text-blue-700 dark:text-blue-300"
                : "bg-secondary text-secondary-foreground";
    return <Badge className={tone}>{channel === "contact_form" ? "Contact Form" : human(channel)}</Badge>;
}
function ContactStatusBadge({ status }: {
    status: string;
}) {
    const styles: Record<string, string> = {
        new: "bg-blue-500/10 text-blue-700 dark:text-blue-300",
        read: "bg-secondary text-secondary-foreground",
        replied: "bg-emerald-500/10 text-emerald-700 dark:text-emerald-300",
        archived: "bg-orange-500/10 text-orange-700 dark:text-orange-300",
    };
    return <Badge className={styles[status] ?? "bg-secondary text-secondary-foreground"}>{human(status)}</Badge>;
}
function ChannelCard({ icon, title, ready, rows }: {
    icon: ReactNode;
    title: string;
    ready: boolean;
