          <div className="flex items-center gap-2">
            <div className="text-primary [&_svg]:h-5 [&_svg]:w-5">{icon}</div>
            <CardTitle className="text-base">{title}</CardTitle>
          </div>
          <Badge className={ready ? "bg-emerald-500/10 text-emerald-700 dark:text-emerald-300" : "bg-red-500/10 text-red-700 dark:text-red-300"}>
            {ready ? "Ready" : "Missing"}
          </Badge>
        </div>
      </CardHeader>
      <CardContent className="space-y-2">
        {rows.map(([label, value]) => (<div key={label} className="flex items-center justify-between rounded-lg border bg-background/35 px-3 py-2 text-sm">
            <span className="text-muted-foreground">{label}</span>
            <span className="font-medium">{value}</span>
          </div>))}
      </CardContent>
