          <TableBody>
            {submissions.map((s) => (<TableRow key={s.id} className="cursor-pointer hover:bg-accent/45" tabIndex={0} onClick={() => onSelect(s)} onKeyDown={(e) => { if (e.key === "Enter" || e.key === " ") {
