}
function ContactCalendarView({ submissions, month, onMonthChange, selectedDay, onDaySelect, onSelect, }: {
    submissions: ContactSubmission[];
    month: Date;
    onMonthChange: (d: Date) => void;
    selectedDay: string | null;
    onDaySelect: (day: string | null) => void;
    onSelect: (s: ContactSubmission) => void;
}) {
    const year = month.getFullYear();
    const monthNum = month.getMonth();
    const firstDayOfWeek = new Date(year, monthNum, 1).getDay();
    const daysInMonth = new Date(year, monthNum + 1, 0).getDate();
    const monthLabel = new Intl.DateTimeFormat("en-US", { month: "long", year: "numeric" }).format(month);
    const todayKey = new Date().toISOString().slice(0, 10);
    const dayMap = new Map<string, number>();
    submissions.forEach((s) => {
        const key = s.created_at.slice(0, 10);
        dayMap.set(key, (dayMap.get(key) ?? 0) + 1);
    });
    const cells: (number | null)[] = [
        ...Array(firstDayOfWeek).fill(null),
        ...Array.from({ length: daysInMonth }, (_, i) => i + 1),
    ];
    while (cells.length % 7 !== 0)
        cells.push(null);
    const filteredSubs = selectedDay ? submissions.filter((s) => s.created_at.startsWith(selectedDay)) : submissions;
    return (<div className="grid gap-6 lg:grid-cols-[300px_1fr]">
      <Card className="h-fit">
        <CardHeader className="pb-3">
          <div className="flex items-center justify-between">
            <button onClick={() => onMonthChange(new Date(year, monthNum - 1, 1))} className="grid h-7 w-7 place-items-center rounded-md hover:bg-accent">
              <ChevronLeft className="h-4 w-4"/>
            </button>
            <span className="text-sm font-semibold">{monthLabel}</span>
            <button onClick={() => onMonthChange(new Date(year, monthNum + 1, 1))} className="grid h-7 w-7 place-items-center rounded-md hover:bg-accent">
              <ChevronRight className="h-4 w-4"/>
            </button>
          </div>
        </CardHeader>
        <CardContent>
          <div className="mb-1 grid grid-cols-7">
            {["Su", "Mo", "Tu", "We", "Th", "Fr", "Sa"].map((d) => (<div key={d} className="py-1 text-center text-[10px] font-medium text-muted-foreground">{d}</div>))}
          </div>
          <div className="grid grid-cols-7 gap-0.5">
            {cells.map((day, i) => {
            if (!day)
                return <div key={`e-${i}`} className="aspect-square"/>;
            const key = `${year}-${String(monthNum + 1).padStart(2, "0")}-${String(day).padStart(2, "0")}`;
            const count = dayMap.get(key) ?? 0;
            const isSelected = selectedDay === key;
            const isToday = key === todayKey;
            return (<button key={key} onClick={() => onDaySelect(isSelected ? null : key)} className={cn("relative flex aspect-square flex-col items-center justify-center rounded-md text-xs transition-colors", isSelected ? "bg-primary text-primary-foreground font-semibold" : "hover:bg-accent", isToday && !isSelected && "font-bold text-primary", count > 0 && !isSelected && "bg-primary/8")}>
                  <span>{day}</span>
                  {count > 0 && (<span className={cn("absolute bottom-0 text-[8px] font-bold leading-tight", isSelected ? "text-primary-foreground/80" : "text-primary")}>{count}</span>)}
                </button>);
        })}
          </div>
          <div className="mt-3 border-t pt-3 text-xs text-muted-foreground">
            {selectedDay ? (<div className="flex items-center justify-between">
                <span>
                  {filteredSubs.length} submission{filteredSubs.length !== 1 ? "s" : ""} on{" "}
                  {new Date(selectedDay + "T12:00:00").toLocaleDateString("en-US", { month: "short", day: "numeric" })}
                </span>
                <button onClick={() => onDaySelect(null)} className="underline hover:text-foreground">Clear</button>
              </div>) : (<span className="block text-center">Click a day to filter</span>)}
          </div>
        </CardContent>
      </Card>

      <div>
        <ContactListView submissions={filteredSubs} onSelect={onSelect}/>
      </div>
    </div>);
}
// ─── Detail sheet for contact submissions ────────────────────────────────────
const STATUS_OPTIONS = [
