function CreateOrderSheet({ open, onOpenChange, data, onCreated }: {
    open: boolean;
    onOpenChange: (open: boolean) => void;
    data: AdminDashboardData | null;
    onCreated: (orderId: string) => Promise<void>;
}) {
    const users = data?.users ?? [];
    const products = data?.products ?? [];
    const [userId, setUserId] = useState("manual");
    const [productId, setProductId] = useState("none");
    const [quantity, setQuantity] = useState("1");
    const [unitPrice, setUnitPrice] = useState("");
    const [status, setStatus] = useState("new");
    const [paymentStatus, setPaymentStatus] = useState("unpaid");
    const [productionStatus, setProductionStatus] = useState("new");
    const [company, setCompany] = useState("");
    const [email, setEmail] = useState("");
    const [phone, setPhone] = useState("");
    const [dueAt, setDueAt] = useState("");
    const [shippingMethod, setShippingMethod] = useState("pickup");
    const [customerNotes, setCustomerNotes] = useState("");
    const [internalNotes, setInternalNotes] = useState("");
    const [couponCode, setCouponCode] = useState("");
    const [couponValidating, setCouponValidating] = useState(false);
    const [couponResult, setCouponResult] = useState<{
        id: string;
        code: string;
        discount_type: string;
        discount_value: number;
        discount_amount: number;
    } | null>(null);
    const [saving, setSaving] = useState(false);
    const [message, setMessage] = useState("");
    const selectedUser = users.find((user) => user.id === userId);
    const selectedProduct = products.find((product) => product.id === productId);
    async function validateCoupon() {
        const code = couponCode.trim().toUpperCase();
        if (!code)
            return;
        const subtotal = Number(quantity || 1) * Number(unitPrice || 0);
        setCouponValidating(true);
        setMessage("");
        try {
            const db = getSupabaseBrowserClient();
            const sessionResult = await db?.auth.getSession();
            const token = sessionResult?.data.session?.access_token;
            const res = await sourceFetch("/api/ctrlp/checkout/validate-coupon", {
                method: "POST",
                headers: { "content-type": "application/json", ...(token ? { authorization: `Bearer ${token}` } : {}) },
                body: JSON.stringify({ code, order_total: subtotal }),
            });
            const data = await res.json();
            if (!res.ok) {
                setMessage(data.error || "Invalid coupon.");
                setCouponResult(null);
            }
            else {
                setCouponResult({ ...data.coupon, discount_amount: data.discount_amount });
                setMessage(`Coupon applied: saves ${money.format(data.discount_amount)}`);
            }
        }
        catch {
            setMessage("Could not validate coupon.");
        }
        finally {
            setCouponValidating(false);
        }
    }
    useEffect(() => {
        if (!open)
            return;
        setProductId(products[0]?.id || "none");
        setMessage("");
    }, [open, products]);
    useEffect(() => {
        if (!selectedUser)
            return;
        setCompany(selectedUser.company || "");
        setEmail(selectedUser.email || "");
        setPhone(selectedUser.phone || "");
    }, [selectedUser]);
    useEffect(() => {
        if (!selectedProduct)
            return;
        setUnitPrice(String(selectedProduct.sale_price || selectedProduct.base_price || 0));
    }, [selectedProduct]);
    async function create() {
        if (productId === "none") {
            setMessage("Select a product before creating the order.");
            return;
        }
        setSaving(true);
        setMessage("Creating order...");
        try {
            const order = await createAdminOrder({ userId: userId === "manual" ? undefined : userId, productId, quantity: Number(quantity || 1), unitPrice: Number(unitPrice || 0), couponCode: couponResult?.code || undefined, status, paymentStatus, productionStatus, company, customerEmail: email, customerPhone: phone, customerNotes, internalNotes, dueAt, shippingMethod });
            await onCreated(order.id);
            onOpenChange(false);
        }
        catch (error) {
            setMessage(error instanceof Error ? error.message : "Could not create order.");
        }
        finally {
            setSaving(false);
        }
    }
    return <Sheet open={open} onOpenChange={onOpenChange}><SheetContent className="overflow-y-auto sm:max-w-[60rem]"><SheetHeader><SheetTitle>Create order</SheetTitle><SheetDescription>Add the customer, user, product, payment, artwork, production, and shipping starting point for a new order.</SheetDescription></SheetHeader><div className="mt-6 space-y-4"><div className="grid gap-3 sm:grid-cols-3"><FieldSelect label="Customer / user" value={userId} onChange={setUserId} items={[{ value: "manual", label: "Manual customer" }, ...users.map((user) => ({ value: user.id, label: `${user.full_name || user.email || user.id.slice(0, 8)} - ${human(user.role)}` }))]}/><FieldSelect label="Product" value={productId} onChange={setProductId} items={products.map((product) => ({ value: product.id, label: `${product.name} - ${product.sku}` }))} placeholder="Select product"/><div><div className="mb-1.5 text-xs font-medium text-muted-foreground">Quantity</div><Input value={quantity} onChange={(event) => setQuantity(event.target.value)} inputMode="numeric"/></div></div><div className="grid gap-3 sm:grid-cols-3"><div><div className="mb-1.5 text-xs font-medium text-muted-foreground">Unit price</div><Input value={unitPrice} onChange={(event) => setUnitPrice(event.target.value)} inputMode="decimal"/></div><FieldSelect label="Order status" value={status} onChange={setStatus} items={orderStatuses.map((item) => ({ value: item, label: human(item) }))}/><FieldSelect label="Payment status" value={paymentStatus} onChange={setPaymentStatus} items={paymentStatuses.map((item) => ({ value: item, label: human(item) }))}/></div><div className="grid gap-3 sm:grid-cols-3"><FieldSelect label="Production status" value={productionStatus} onChange={setProductionStatus} items={productionStatuses.map((item) => ({ value: item, label: human(item) }))}/><div><div className="mb-1.5 text-xs font-medium text-muted-foreground">Due date</div><DatePicker value={dueAt} onChange={setDueAt}/></div><FieldSelect label="Shipping" value={shippingMethod} onChange={setShippingMethod} items={["pickup", "local_delivery", "ship", "install"].map((item) => ({ value: item, label: human(item) }))}/></div><div className="grid gap-3 sm:grid-cols-3"><div><div className="mb-1.5 text-xs font-medium text-muted-foreground">Company</div><Input value={company} onChange={(event) => setCompany(event.target.value)}/></div><div><div className="mb-1.5 text-xs font-medium text-muted-foreground">Email</div><Input value={email} onChange={(event) => setEmail(event.target.value)}/></div><div><div className="mb-1.5 text-xs font-medium text-muted-foreground">Phone</div><Input value={phone} onChange={(event) => setPhone(event.target.value)}/></div></div><div className="grid gap-3 sm:grid-cols-2"><div><div className="mb-1.5 text-xs font-medium text-muted-foreground">Customer notes</div><Textarea value={customerNotes} onChange={(event) => setCustomerNotes(event.target.value)}/></div><div><div className="mb-1.5 text-xs font-medium text-muted-foreground">Internal notes</div><Textarea value={internalNotes} onChange={(event) => setInternalNotes(event.target.value)}/></div></div><div><div className="mb-1.5 text-xs font-medium text-muted-foreground">Coupon code</div><div className="flex gap-2">{couponResult ? (<div className="flex flex-1 items-center justify-between rounded-lg border border-emerald-500/30 bg-emerald-500/10 px-3 py-2 text-sm text-emerald-700 dark:text-emerald-300"><span>{couponResult.code} — saves {money.format(couponResult.discount_amount)}</span><button type="button" onClick={() => { setCouponResult(null); setCouponCode(""); setMessage(""); }} className="ml-2 text-xs underline">Remove</button></div>) : (<><Input value={couponCode} onChange={(e) => setCouponCode(e.target.value.toUpperCase())} onKeyDown={(e) => e.key === "Enter" && validateCoupon()} placeholder="COUPON CODE" className="font-mono uppercase"/><Button type="button" variant="outline" onClick={validateCoupon} disabled={couponValidating || !couponCode.trim()}>{couponValidating ? "..." : "Apply"}</Button></>)}</div></div><div className="rounded-lg border bg-secondary/25 px-3 py-2 text-sm text-muted-foreground">{couponResult ? <>Estimated total: {money.format(Math.max(0, Number(quantity || 1) * Number(unitPrice || 0) - couponResult.discount_amount))} (after {couponResult.discount_type === "percentage" ? `${couponResult.discount_value}% discount` : `$${couponResult.discount_value} discount`}).</> : <>Estimated total: {money.format(Number(quantity || 1) * Number(unitPrice || 0))}.</>} A production job is created automatically for the selected product.</div>{message && <div className="rounded-lg border bg-background/35 p-3 text-sm text-muted-foreground">{message}</div>}<div className="flex gap-2"><Button className="flex-1" onClick={create} disabled={saving}>{saving ? "Creating..." : "Create order"}</Button><Button variant="outline" onClick={() => onOpenChange(false)}>Cancel</Button></div></div></SheetContent></Sheet>;
}
function OrderDrawer({ order, data, open, onOpenChange, onRefresh }: {
    order: Order | null;
    data: AdminDashboardData | null;
    open: boolean;
    onOpenChange: (open: boolean) => void;
    onRefresh: (orderId?: string) => Promise<void>;
}) {
    const [status, setStatus] = useState("new");
    const [paymentStatus, setPaymentStatus] = useState("unpaid");
    const [productionStatus, setProductionStatus] = useState("new");
    const [dueAt, setDueAt] = useState("");
    const [notes, setNotes] = useState("");
    const [saving, setSaving] = useState(false);
    const [message, setMessage] = useState("");
    const items = (data?.orderItems ?? []).filter((item) => item.order_id === order?.id);
    const payments = (data?.payments ?? []).filter((payment) => payment.order_id === order?.id);
    const messages = (data?.messages ?? []).filter((item) => item.order_id === order?.id);
    const jobs = (data?.productionJobs ?? []).filter((job) => job.order_id === order?.id);
    const artwork = (data?.artworkFiles ?? []).filter((file) => file.order_id === order?.id || items.some((item) => item.id === file.order_item_id));
    const proofs = (data?.proofs ?? []).filter((proof) => items.some((item) => item.id === proof.order_item_id));
