ts?.name || "Unassigned product"} detail={`${item.products?.category || "Catalog"} - Qty ${item.quantity}`} value={money.format(numberValue(item.line_total))}/>)}</Section><Section title="Payments" count={payments.length}>{payments.map((payment) => <Row key={payment.id} title={`${human(payment.provider)} ${human(payment.status)}`} detail={payment.payment_link_url || payment.notes || "Payment record"} value={money.format(numberValue(payment.amount))}/>)}</Section><Section title="Artwork and proofs" count={artwork.length + proofs.length}>{artwork.map((file) => <Row key={file.id} title={file.filename} detail={human(file.review_status)} value={fileSize(file.file_size_bytes)}/>)}{proofs.map((proof) => <Row key={proof.id} title={`Proof v${proof.revision_number || 1}`} detail={human(proof.status)} value={proof.customer_approved_at ? "Approved" : "Open"}/>)}</Section><Section title="Production / shipping" count={jobs.length}>{jobs.map((job) => <Row key={job.id} title={job.station || "Production"} detail={human(job.status)} value={job.due_at ? new Date(job.due_at).toLocaleDateString() : "No due"}/>)}</Section><Section title="Messages and notes" count={messages.length}>{messages.map((item) => <Row key={item.id} title={item.subject || human(item.channel)} detail={item.body || human(item.direction)} value={human(item.channel)}/>)}</Section></div></div>}</SheetContent></Sheet>;
}
function FieldSelect({ label, value, onChange, items, placeholder }: {
    label: string;
    value: string;
    onChange: (value: string) => void;
    items: {
        value: string;
        label: string;
    }[];
    placeholder?: string;
}) {
    return <div><div className="mb-1.5 text-xs font-medium text-muted-foreground">{label}</div><Select value={value} onValueChange={onChange}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent>{placeholder && <SelectItem value="none">{placeholder}</SelectItem>}{items.map((item) => <SelectItem key={item.value} value={item.value}>{item.label}</SelectItem>)}</SelectContent></Select></div>;
}
function LinkedMeta({ label, value, subvalue }: {
    label: string;
    value: string;
    subvalue?: string;
}) {
    return <div className="rounded-lg border bg-secondary/25 px-3 py-2"><div className="text-[10px] font-semibold uppercase tracking-wide text-muted-foreground">{label}</div><div className="mt-1 break-words text-sm font-medium">{value}</div>{subvalue && <div className="mt-1 break-words text-xs text-muted-foreground">{subvalue}</div>}</div>;
}
function Section({ title, count, children }: {
    title: string;
    count: number;
    children: React.ReactNode;
}) {
    return <div><div className="mb-2 flex items-center justify-between"><h3 className="text-sm font-semibold">{title}</h3><Badge variant="outline">{count}</Badge></div><div className="space-y-2">{count ? children : <div className="rounded-lg border border-dashed p-3 text-sm text-muted-foreground">No records yet.</div>}</div></div>;
}
function Row({ title, detail, value }: {
    title: string;
    detail: string;
    value: string;
}) {
    return <div className="flex items-center justify-between gap-3 rounded-lg border bg-background/35 p-3"><div className="min-w-0"><div className="truncate text-sm font-medium">{title}</div><div className="truncate text-xs text-muted-foreground">{detail}</div></div><Badge variant="outline">{value}</Badge></div>;
}
function fileSize(value: number | string | null | undefined) {
    const bytes = Number(value || 0);
    if (!bytes)
        return "Unknown";
    if (bytes > 1024 * 1024)
        return `${(bytes / 1024 / 1024).toFixed(1)} MB`;
    return `${Math.max(1, Math.round(bytes / 1024))} KB`;
}

