async function getAdminToken() {
    const db = getSupabaseBrowserClient();
    if (!db)
        throw new Error("Supabase is not configured.");
    const sessionResult = await db.auth.getSession();
    const token = sessionResult.data.session?.access_token;
    if (!token)
        throw new Error("Sign in again before managing production schedule.");
    return token;
}
async function apiJson<T>(url: string, init?: RequestInit): Promise<T> {
    const token = await getAdminToken();
    const response = await sourceFetch(url, {
        ...init,
        headers: {
            "content-type": "application/json",
            authorization: `Bearer ${token}`,
            ...(init?.headers || {}),
        },
    });
    const payload = await response.json().catch(() => ({}));
    if (!response.ok) {
        const error = payload as {
            error?: string;
        };
        throw new Error(error.error || "Schedule request failed.");
    }
    return payload as T;
}
async function apiFormData<T>(url: string, form: FormData): Promise<T> {
    const token = await getAdminToken();
    const response = await sourceFetch(url, {
        method: "POST",
        headers: {
            authorization: `Bearer ${token}`,
        },
        body: form,
    });
    const payload = await response.json().catch(() => ({}));
    if (!response.ok) {
        const error = payload as {
            error?: string;
        };
        throw new Error(error.error || "Upload request failed.");
    }
    return payload as T;
}
