type ConnectorSide = "start" | "finish";
type DependencyPath = {
    id: string;
    d: string;
    sourceId: string;
    targetId: string;
    dependencyType: string;
    blocked: boolean;
    complete: boolean;
};
type GanttDrag = {
    item: ScheduleItem;
    mode: "move" | "resize-start" | "resize-end";
    pointerStartX: number;
    pointerStartY: number;
    pointerX: number;
    pointerY: number;
    originalStart: string;
    originalEnd: string;
    originalOffsetMinutes: number;
    originalSortOrder: number;
    originalDurationDays: number;
    previewStart: string;
    previewEnd: string;
    previewOffsetMinutes: number;
    previewSortOrder: number;
    previewDurationDays: number;
    moved: boolean;
};
type GanttActionDockState = {
    item: ScheduleItem;
    x: number;
    y: number;
};
function dependencyTypeFromSides(sourceSide: ConnectorSide, targetSide: ConnectorSide) {
    if (sourceSide === "finish" && targetSide === "start")
        return "finish_to_start";
    if (sourceSide === "start" && targetSide === "start")
        return "start_to_start";
    if (sourceSide === "finish" && targetSide === "finish")
        return "finish_to_finish";
    return "start_to_finish";
}
function connectorX(rect: DOMRect, side: ConnectorSide) {
    return side === "finish" ? rect.right : rect.left;
}
function sideFromDependency(type: string, role: "source" | "target"): ConnectorSide {
    if (type === "start_to_start")
        return "start";
    if (type === "finish_to_finish")
        return "finish";
    if (type === "start_to_finish")
        return role === "source" ? "start" : "finish";
    return role === "source" ? "finish" : "start";
}
function GanttTimeline({ items, dependencies, projectLabel, onEdit, onAddTask, onHide, onCancel, onComplete, onDelete, onQuickAction, onUpdateItemDates, onCreateDependency, onSelectDependency, relationSummaries, }: {
