        const m = mins % 60;
        const period = h >= 12 ? "p" : "a";
        const hour = h % 12 || 12;
        return m === 0 ? `${hour}${period}` : `${hour}:${m.toString().padStart(2, "0")}${period}`;
    }
    function itemsForDay(day: Date): ScheduleItem[] {
        const key = dateOnly(day);
        const dayItems = items.filter((item) => item.start_date === key || item.due_date === key || item.end_date === key);
        return dayItems.sort((a, b) => {
            // Appointments rise to top, sorted by start time; tasks follow
            if (a.source_type === "appointment" && b.source_type !== "appointment")
                return -1;
            if (a.source_type !== "appointment" && b.source_type === "appointment")
                return 1;
            if (a.source_type === "appointment" && b.source_type === "appointment") {
                return (a.start_offset_minutes ?? 0) - (b.start_offset_minutes ?? 0);
            }
            return 0;
        });
    }
    const unscheduled = items.filter((item) => !item.start_date && !item.due_date && !item.end_date && item.source_type !== "appointment");
    function barClass(item: ScheduleItem) {
        if (item.source_type === "appointment")
            return "bg-sky-500/20 text-sky-800 dark:text-sky-200 border-sky-500/30";
        if (item.is_blocked || item.status === "blocked")
            return "bg-red-500/20 text-red-700 dark:text-red-200 border-red-500/30";
        if (["completed", "approved"].includes(item.status))
            return "bg-emerald-500/20 text-emerald-700 dark:text-emerald-200 border-emerald-500/30";
        return "bg-primary/20 text-lime-900 dark:text-lime-100 border-primary/30";
    }
    function prevPeriod() {
        if (calMode === "month")
            setViewDate(new Date(year, month - 1, 1));
        else
            setViewDate((prev) => new Date(prev.getFullYear(), prev.getMonth(), prev.getDate() - 7));
    }
    function nextPeriod() {
        if (calMode === "month")
            setViewDate(new Date(year, month + 1, 1));
        else
            setViewDate((prev) => new Date(prev.getFullYear(), prev.getMonth(), prev.getDate() + 7));
    }
    const calLegend = [
        { label: "Appointment", cls: "bg-sky-500/20 border-sky-500/30" },
        { label: "Task / Milestone", cls: "bg-primary/20 border-primary/30" },
        { label: "Completed", cls: "bg-emerald-500/20 border-emerald-500/30" },
        { label: "Blocked", cls: "bg-red-500/20 border-red-500/30" },
    ];
    return (<Card>
      <CardHeader className="pb-3">
        <div className="flex flex-wrap items-center justify-between gap-3">
          <div>
            <CardTitle className="text-base">Calendar view</CardTitle>
            <CardDescription>Tasks, milestones, due dates, installs, deliveries, and appointments.</CardDescription>
          </div>
          <div className="flex flex-wrap items-center gap-2">
            <div className="flex overflow-hidden rounded-md border">
              <button className={cn("px-3 py-1.5 text-xs font-medium transition-colors", calMode === "month" ? "bg-primary text-primary-foreground" : "bg-background text-muted-foreground hover:bg-accent")} onClick={() => setCalMode("month")}>Month</button>
              <button className={cn("border-l px-3 py-1.5 text-xs font-medium transition-colors", calMode === "week" ? "bg-primary text-primary-foreground" : "bg-background text-muted-foreground hover:bg-accent")} onClick={() => setCalMode("week")}>Week</button>
            </div>
            <Button variant="outline" size="icon" className="h-8 w-8" onClick={prevPeriod}><ChevronLeft className="h-4 w-4"/></Button>
            <span className="min-w-[160px] text-center text-sm font-semibold">{calMode === "month" ? monthLabel : weekLabel}</span>
            <Button variant="outline" size="icon" className="h-8 w-8" onClick={nextPeriod}><ChevronRight className="h-4 w-4"/></Button>
            <Button variant="outline" size="sm" className="h-8" onClick={() => setViewDate(new Date())}>Today</Button>
          </div>
        </div>
      </CardHeader>
      <CardContent>

        {calMode === "month" ? (<div className="grid grid-cols-7 gap-px rounded-lg border bg-border overflow-hidden">
            {["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"].map((d) => (<div key={d} className="bg-muted/60 py-2 text-center text-[11px] font-semibold uppercase tracking-wide text-muted-foreground">{d}</div>))}
            {calDays.map((day, i) => {
                if (!day)
                    return <div key={`empty-${i}`} className="min-h-[90px] bg-muted/20"/>;
                const dayStr = dateOnly(day);
                const dayItems = itemsForDay(day);
                const isToday = dayStr === todayStr;
                return (<div key={dayStr} className={cn("min-h-[90px] bg-background p-1.5 transition-colors hover:bg-accent/20", isToday && "bg-primary/5 ring-1 ring-inset ring-primary/40")}>
                  <div className={cn("mb-1 flex h-5 w-5 items-center justify-center rounded-full text-xs font-medium", isToday && "bg-primary text-primary-foreground font-bold")}>
                    {day.getDate()}
                  </div>
                  <div className="space-y-0.5">
                    {dayItems.slice(0, 3).map((item) => (<button key={item.id} title={item.title} className={cn("block w-full truncate rounded border px-1.5 py-0.5 text-left text-[10px] font-medium leading-4 transition-opacity hover:opacity-80", barClass(item))} onClick={() => onSelect(item)}>
                        {item.source_type === "appointment" && item.start_offset_minutes != null
                            ? `${minutesToTime(item.start_offset_minutes)} · ${item.title}`
                            : item.title}
                      </button>))}
                    {dayItems.length > 3 && (<div className="px-1 text-[10px] text-muted-foreground">+{dayItems.length - 3} more</div>)}
                  </div>
                </div>);
            })}
          </div>) : (<div className="overflow-x-auto">
            <div className="grid grid-cols-7 gap-px overflow-hidden rounded-lg border bg-border" style={{ minWidth: 560 }}>
              {weekDays.map((day) => {
                const dayStr = dateOnly(day);
                const isToday = dayStr === todayStr;
                const dayItems = itemsForDay(day);
                const appts = dayItems.filter((item) => item.source_type === "appointment");
                const tasks = dayItems.filter((item) => item.source_type !== "appointment");
                return (<div key={dayStr} className={cn("flex min-h-[200px] flex-col bg-background", isToday && "bg-primary/5")}>
                    <div className={cn("border-b px-2 py-1.5 text-center", isToday && "bg-primary/10")}>
                      <div className="text-[11px] font-semibold uppercase tracking-wide text-muted-foreground">
                        {new Intl.DateTimeFormat("en-US", { weekday: "short" }).format(day)}
                      </div>
                      <div className={cn("mx-auto mt-0.5 flex h-6 w-6 items-center justify-center rounded-full text-xs font-bold", isToday ? "bg-primary text-primary-foreground" : "text-foreground")}>
                        {day.getDate()}
                      </div>
                    </div>
                    <div className="flex-1 space-y-0.5 p-1">
                      {appts.map((item) => (<button key={item.id} className={cn("block w-full rounded border px-1.5 py-1 text-left transition-opacity hover:opacity-80", barClass(item))} onClick={() => onSelect(item)}>
                          {item.start_offset_minutes != null && (<div className="text-[9px] font-semibold leading-3 opacity-80">{minutesToTime(item.start_offset_minutes)}</div>)}
                          <div className="truncate text-[10px] font-medium leading-4">{item.title}</div>
                        </button>))}
                      {tasks.map((item) => (<button key={item.id} className={cn("block w-full truncate rounded border px-1.5 py-0.5 text-left text-[10px] font-medium leading-4 transition-opacity hover:opacity-80", barClass(item))} onClick={() => onSelect(item)}>
                          {item.title}
                        </button>))}
                      {dayItems.length === 0 && (<div className="pt-4 text-center text-[10px] text-muted-foreground/40">—</div>)}
                    </div>
                  </div>);
            })}
            </div>
          </div>)}

        {/* Legend */}
        <div className="mt-3 flex flex-wrap items-center gap-x-4 gap-y-1.5 border-t pt-3">
          {calLegend.map(({ label, cls }) => (<span key={label} className="flex items-center gap-1.5 text-[11px] text-muted-foreground">
              <span className={cn("h-2.5 w-2.5 rounded-sm border", cls)}/>
              {label}
            </span>))}
        </div>

        {unscheduled.length > 0 && (<div className="mt-4">
            <div className="mb-2 text-xs font-semibold uppercase tracking-wide text-muted-foreground">Unscheduled ({unscheduled.length})</div>
            <div className="grid gap-2 sm:grid-cols-2 xl:grid-cols-3">
              {unscheduled.map((item) => (<ScheduleItemMiniCard key={item.id} item={item} relationSummaries={relationSummaries} onSelect={onSelect}/>))}
            </div>
          </div>)}

        {!items.length && <EmptyState title="No calendar items" description="Adjust filters or include appointments to populate the calendar."/>}
      </CardContent>
    </Card>);
}
function WorkflowTemplatePanel({ templates, orders, orderItems, users, products, productionJobs, onApply, expanded, }: {
    templates: WorkflowTemplate[];
    orders: Order[];
    orderItems: OrderItem[];
    users: AdminUser[];
    products: Product[];
    productionJobs: ProductionJob[];
    onApply: (input: {
        template_slug: string;
        project_name: string;
        start_date: string;
        order_id: string | null;
        order_item_id: string | null;
        production_job_id: string | null;
        product_id: string | null;
        customer_id: string | null;
    }) => Promise<void>;
    expanded?: boolean;
}) {
    const [templateSlug, setTemplateSlug] = useState(templates[0]?.slug || "none");
