        internal_notes: "",
        customer_notes: "",
    };
}
function payloadFromItem(item?: ScheduleItem | null): SchedulePayload {
    if (!item)
        return emptyPayload();
    return {
        id: item.id,
        order_id: item.order_id,
        order_item_id: item.order_item_id,
