function DateField({ label, value, onChange }: {
    label: string;
    value: string;
    onChange: (value: string) => void;
}) {
    const [open, setOpen] = useState(false);
    const selected = value ? new Date(`${value}T12:00:00`) : new Date();
    const [visibleMonth, setVisibleMonth] = useState(() => new Date(selected.getFullYear(), selected.getMonth(), 1));
    const monthLabel = new Intl.DateTimeFormat("en-US", { month: "long", year: "numeric" }).format(visibleMonth);
    const firstDay = visibleMonth.getDay();
    const gridStart = addDays(visibleMonth, -firstDay);
    const days = Array.from({ length: 42 }, (_, index) => addDays(gridStart, index));
    const today = dateOnly(new Date());
    function choose(day: Date) {
        onChange(dateOnly(day));
        setVisibleMonth(new Date(day.getFullYear(), day.getMonth(), 1));
        setOpen(false);
    }
    return (<div className="relative">
      <div className="mb-1.5 text-xs font-medium text-muted-foreground">{label}</div>
      <button type="button" className="flex h-10 w-full items-center justify-between rounded-md border border-input bg-background px-3 py-2 text-left text-sm text-foreground shadow-sm ring-offset-background transition-colors hover:border-primary/60 focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2" onClick={() => setOpen((current) => !current)}>
        <span>{value ? new Intl.DateTimeFormat("en-US", { month: "2-digit", day: "2-digit", year: "numeric" }).format(selected) : "Select date"}</span>
        <Calendar className="h-4 w-4 text-muted-foreground"/>
      </button>
      {open && (<div className="absolute left-0 top-[4.4rem] z-[70] w-[320px] rounded-lg border bg-card p-3 text-card-foreground shadow-xl">
          <div className="mb-3 flex items-center justify-between">
            <Button variant="ghost" size="icon" className="h-8 w-8" onClick={() => setVisibleMonth(new Date(visibleMonth.getFullYear(), visibleMonth.getMonth() - 1, 1))}>
              <ChevronLeft className="h-4 w-4"/>
            </Button>
            <div className="text-sm font-semibold">{monthLabel}</div>
            <Button variant="ghost" size="icon" className="h-8 w-8" onClick={() => setVisibleMonth(new Date(visibleMonth.getFullYear(), visibleMonth.getMonth() + 1, 1))}>
              <ChevronRight className="h-4 w-4"/>
            </Button>
          </div>
          <div className="grid grid-cols-7 gap-1 text-center text-[11px] font-semibold text-muted-foreground">
            {["Su", "Mo", "Tu", "We", "Th", "Fr", "Sa"].map((day) => <div key={day} className="py-1">{day}</div>)}
          </div>
          <div className="grid grid-cols-7 gap-1">
            {days.map((day) => {
                const key = dateOnly(day);
                const selectedDay = value === key;
                const inMonth = day.getMonth() === visibleMonth.getMonth();
                return (<button type="button" key={key} className={cn("grid h-9 place-items-center rounded-md text-sm transition-colors hover:bg-primary hover:text-primary-foreground", !inMonth && "text-muted-foreground/55", key === today && "border border-primary/50", selectedDay && "bg-primary font-semibold text-primary-foreground shadow-sm")} onClick={() => choose(day)}>
                  {day.getDate()}
                </button>);
            })}
          </div>
          <div className="mt-3 flex items-center justify-between border-t pt-3">
            <Button variant="ghost" size="sm" onClick={() => { onChange(""); setOpen(false); }}>Clear</Button>
            <Button variant="outline" size="sm" onClick={() => choose(new Date())}>Today</Button>
          </div>
        </div>)}
    </div>);
}
function ToggleRow({ label, description, checked, onChange }: {
    label: string;
    description: string;
    checked: boolean;
    onChange: (checked: boolean) => void;
}) {
    return (<label className="flex cursor-pointer items-start gap-3 rounded-lg border bg-secondary/20 p-3">
