      </span>
    </label>);
}
function LinkedMeta({ label, value, subvalue }: {
    label: string;
    value: string;
    subvalue?: string;
}) {
    return (<div className="rounded-lg border bg-secondary/25 px-3 py-2">
      <div className="text-[10px] font-semibold uppercase tracking-wide text-muted-foreground">{label}</div>
