    const [message, setMessage] = useState("");
    useEffect(() => {
        if (!open)
            return;
        setOrderId(shipment?.order_id || orders[0]?.id || "none");
        setCarrier(shipment?.carrier || "ups");
        setTrackingNumber(shipment?.tracking_number || "");
        setTrackingUrl(shipment?.tracking_url || "");
